  testq %rdi, %rdi
  js .Llen0
  movabsq $2097152, %rdx
  cmpq %rdx, %rdi
  jg .Llen0
  leaq mjz_alen(%rip), %rdx
  movq (%rdx,%rdi,8), %rax
  ret
.Llen0:
  xorl %eax, %eax
  ret
# int64 mjz_load(int64 h, int64 i): TRAPs unless 0 <= i < len[h]
mjz_load:
  testq %rdi, %rdi
  js mjz_trap
  movabsq $2097152, %rdx
  cmpq %rdx, %rdi
  jg mjz_trap
  testq %rsi, %rsi
  js mjz_trap
  leaq mjz_alen(%rip), %rdx
  movq (%rdx,%rdi,8), %rcx
  cmpq %rcx, %rsi
  jge mjz_trap
  leaq mjz_arena(%rip), %rdx
  addq %rdi, %rsi
  movq (%rdx,%rsi,8), %rax
  ret
# void mjz_store(int64 h, int64 i, int64 v)
mjz_store:
  testq %rdi, %rdi
  js mjz_trap
  movabsq $2097152, %r8
  cmpq %r8, %rdi
  jg mjz_trap
  testq %rsi, %rsi
  js mjz_trap
  leaq mjz_alen(%rip), %r9
  movq (%r9,%rdi,8), %rcx
  cmpq %rcx, %rsi
  jge mjz_trap
  leaq mjz_arena(%rip), %r9
  addq %rdi, %rsi
  movq %rdx, (%r9,%rsi,8)
  ret
# int64 mjz_input(void): scanf into stack scratch; 0 on EOF/failure
mjz_input:
  pushq %rbx
  subq $16, %rsp
  leaq .Lscan(%rip), %rdi
  movq $0, (%rsp)
  movq %rsp, %rsi
  xorl %eax, %eax
  call scanf
  movq (%rsp), %rax
  addq $16, %rsp
  popq %rbx
  ret
  .section .rodata
.Lfmt:
  .string "%lld\n"
.Ltraps:
  .string "TRAP"
.Lscan:
  .string "%lld"
  .section .bss
  .balign 32
mjz_arena:
  .zero 16777224
mjz_alen:
  .zero 16777224
mjz_atop:
